// declining rather than a bug: an uninsurable type, an uncovered item, an absent
// policy. Each names its own offender; this says once what they share — a miss
// is a domain error, never an undefined that travels on.
const foundOrThrow = <Found,>(found: Found | undefined, declined: () => string): Found => {
  if (found === undefined) {
    throw new Error(declined());
  }
  return found;
};

